#!/usr/bin/env node
// Generates the per-workstream issue templates + config.yml for the
// sorcery-labs org `.github` repo (the org-wide default templates).
//
// To change templates: edit the WORKSTREAMS list or the shared BODY below,
// then re-run:   node scripts/generate-issue-templates.mjs
//
// The generated files are marked GENERATED — don't hand-edit them; edit this
// generator and regenerate so all templates stay in sync (DRY).
//
// NOT managed here: infrastructure-change.yaml (the cross-repo change template
// is hand-maintained because it has a bespoke body).

import { writeFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const GH_DIR = fileURLToPath(new URL('../.github', import.meta.url));
const OUT_DIR = `${GH_DIR}/ISSUE_TEMPLATE`;

// One entry per template. Most workstreams = one template; Platform is split
// into two static "area" variants so the area:* label is guaranteed at
// creation (a static `labels:` list can't make a runtime choice).
const WORKSTREAMS = [
  { slug: 'super-duper',         name: 'Super-duper',            labels: ['workstream:super-duper'] },
  { slug: 'trading',             name: 'Trading',                labels: ['workstream:trading'] },
  { slug: 'tiny-markets',        name: 'Tiny-markets',           labels: ['workstream:tiny-markets'] },
  { slug: 'sorcery',             name: 'Sorcery',                labels: ['workstream:sorcery'] },
  { slug: 'platform-infra',      name: 'Platform / IAC',         labels: ['workstream:platform', 'area:iac'] },
  { slug: 'platform-monitoring', name: 'Platform / Monitoring',  labels: ['workstream:platform', 'area:monitoring'] },
];

const HEADER =
  '# GENERATED by scripts/generate-issue-templates.mjs — do not edit by hand;\n' +
  '# edit the generator and re-run so every workstream template stays in sync.\n';

// Shared form body — identical across every workstream template. The workstream
// (and area, for Platform) is fixed by the template's static labels above, so
// there is deliberately no workstream dropdown here.
const BODY = `body:
  - type: dropdown
    id: priority
    attributes:
      label: Priority
      options: [Critical, High, Medium, Low]
    validations:
      required: true
  - type: textarea
    id: summary
    attributes:
      label: What needs to be done?
      placeholder: One-sentence description
    validations:
      required: true
  - type: textarea
    id: context
    attributes:
      label: Context / background
      placeholder: Why does this matter? Link any relevant Notion docs.
  - type: textarea
    id: acceptance
    attributes:
      label: Acceptance criteria
      placeholder: |
        - [ ] Criterion one
        - [ ] Criterion two
  - type: input
    id: notion
    attributes:
      label: Notion doc (optional)
      placeholder: https://notion.so/...
`;

function template({ name, labels }) {
  return `${HEADER}name: ${name} Task
description: ${name} task, feature, or bug
labels: ${JSON.stringify(labels)}
${BODY}`;
}

mkdirSync(OUT_DIR, { recursive: true });

for (const ws of WORKSTREAMS) {
  writeFileSync(`${OUT_DIR}/${ws.slug}-task.yaml`, template(ws));
  console.log(`wrote ${ws.slug}-task.yaml  [${ws.labels.join(', ')}]`);
}

// Force template selection so every issue created via the UI gets a workstream
// label (and Platform issues an area label) at creation.
writeFileSync(`${OUT_DIR}/config.yml`, `${HEADER}blank_issues_enabled: false\n`);
console.log('wrote config.yml');

// --- Label manifest (.github/labels.yml) -----------------------------------
// Inert data file consumed by .github/workflows/sync-labels.yml to create/
// update these labels in every target repo. Produced from the same generator,
// so the templates above and the label set here can't drift apart.
const LABELS = {
  'workstream:super-duper':  { color: '1D76DB', description: 'Super-duper client work' },
  'workstream:trading':      { color: '0E8A16', description: 'Trading ops and dev' },
  'workstream:platform':     { color: '5319E7', description: 'Platform — infra, iac, monitoring' },
  'workstream:sorcery':      { color: 'FBCA04', description: 'Cross-cutting / org-wide catch-all' },
  'workstream:tiny-markets': { color: '006B75', description: 'Tiny-markets work' },
  'area:iac':                { color: 'C5DEF5', description: 'Platform sub-area: iac' },
  'area:monitoring':         { color: 'BFDADC', description: 'Platform sub-area: monitoring / alerting' },
  'blocked':                 { color: 'B60205', description: 'Blocked by another issue (added at triage)' },
};

// Drift guard: every label a template applies must be defined in LABELS.
for (const ws of WORKSTREAMS) {
  for (const name of ws.labels) {
    if (!LABELS[name]) throw new Error(`Template "${ws.slug}" uses undefined label "${name}" — add it to LABELS.`);
  }
}

const labelsYml = `${HEADER}labels:\n` + Object.entries(LABELS).map(
  ([name, meta]) => `  - name: "${name}"\n    color: "${meta.color}"\n    description: "${meta.description}"\n`,
).join('');
writeFileSync(`${GH_DIR}/labels.yml`, labelsYml);
console.log('wrote labels.yml');
